const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "enum AttendanceStatus {\n  PRESENT\n  LATE\n  // Kerja dari rumah — hari kerja penuh, jadi tidak dipotong dan tidak\n  // dihitung sebagai pelanggaran; dibedakan dari PRESENT supaya HR bisa\n  // melihat siapa yang tidak hadir fisik di cabang.\n  WFH\n  ABSENT\n  PERMISSION\n  SICK\n  // Cuti resmi (berbayar) — berbeda dari PERMISSION yang izin insidental.\n  LEAVE\n  HOLIDAY\n}\n\n/// Tanggal merah — hari libur nasional & cuti bersama.\n///\n/// Ada karena alpha diturunkan dari KETIADAAN baris presensi: tanpa daftar ini,\n/// setiap tanggal merah yang lewat tanpa presensi akan dihitung alpha dan\n/// dipotong dari gaji. Hari Minggu tidak perlu dicatat di sini — ia sudah\n/// dikecualikan dari hari kerja (lihat src/lib/workday.ts).\n///\n/// Berlaku untuk SEMUA PT: tanggal merah ditetapkan pemerintah, bukan per\n/// perusahaan. Kalau suatu saat satu PT libur sendiri di tanggal yang bukan\n/// tanggal merah, itu bukan baris di sini melainkan presensi berstatus HOLIDAY.\nmodel PublicHoliday {\n  id           String   @id @default(cuid())\n  date         DateTime @unique @db.Date\n  name         String\n  /// Cuti bersama (bukan hari libur itu sendiri) — dibedakan hanya untuk\n  /// keterangan, keduanya sama-sama bukan hari kerja.\n  isJointLeave Boolean  @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([date])\n}\n\nmodel Attendance {\n  id                String           @id @default(cuid())\n  userId            String\n  branchId          String?\n  date              DateTime         @db.Date\n  checkIn           DateTime?\n  checkOut          DateTime?\n  checkInPhotoUrl   String?\n  checkOutPhotoUrl  String?\n  // GPS from browser navigator.geolocation (auto-captured)\n  checkInGpsLat     Float?\n  checkInGpsLng     Float?\n  // Second location from manual input on the form (to detect GPS spoofing)\n  checkInManualLat  Float?\n  checkInManualLng  Float?\n  isLocationSuspect Boolean          @default(false)\n  isWithDoctorNote  Boolean          @default(false)\n  status            AttendanceStatus @default(PRESENT)\n  notes             String?\n  // Jejak koreksi manual oleh HR/atasan lewat halaman Presensi Karyawan.\n  // Tanpa ini, jam masuk yang diketik orang lain tidak bisa dibedakan dari\n  // jam hasil clock-in karyawan sendiri — padahal keduanya memengaruhi gaji.\n  editedById        String?\n  editedAt          DateTime?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  user     user    @relation(\"AttendanceEmployee\", fields: [userId], references: [id], onDelete: Cascade)\n  editedBy user?   @relation(\"AttendanceEditedBy\", fields: [editedById], references: [id], onDelete: SetNull)\n  branch   Branch? @relation(fields: [branchId], references: [id], onDelete: SetNull)\n\n  @@unique([userId, date])\n  @@index([userId])\n  @@index([branchId])\n  @@index([date])\n  @@index([editedById])\n}\n\nmodel account {\n  id                    String    @id\n  accountId             String\n  providerId            String\n  userId                String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime\n  updatedAt             DateTime\n  user                  user      @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel session {\n  id        String   @id\n  expiresAt DateTime\n  token     String   @unique\n  createdAt DateTime\n  updatedAt DateTime\n  ipAddress String?\n  userAgent String?\n  userId    String\n  user      user     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel custom_role {\n  id                String                   @id @default(cuid())\n  name              String\n  description       String?\n  companyId         String?\n  permissions       String[]\n  payrollCompanyIds String[]                 @default([])\n  /// True setelah jabatan ini dipindahkan ke matriks izin per-resource.\n  /// Penanda ini WAJIB eksplisit, tidak boleh disimpulkan dari \"punya baris\n  /// RoleResourcePermission atau tidak\": mencabut seluruh izin sebuah jabatan\n  /// menyisakan nol baris, dan tanpa penanda ini akses lamanya akan hidup lagi.\n  usesResourcePerms Boolean                  @default(false)\n  createdAt         DateTime                 @default(now())\n  updatedAt         DateTime                 @updatedAt\n  roleKpis          RoleKpi[]\n  company           Company?                 @relation(fields: [companyId], references: [id])\n  users             user[]\n  // Izin per-resource dengan scope PT terpisah untuk baca & tulis.\n  // `permissions` di atas adalah model lama yang masih dibaca selama migrasi\n  // bertahap (lihat src/lib/authz/resolve.ts).\n  resourcePerms     RoleResourcePermission[]\n  payrollSlips      PayrollSlip[]\n\n  @@unique([name, companyId])\n}\n\nmodel user {\n  id            String    @id\n  name          String\n  email         String    @unique\n  emailVerified Boolean\n  image         String?\n  createdAt     DateTime\n  updatedAt     DateTime\n  phone         String?\n  branchId      String?\n  baseSalary    Decimal?\n  joinDate      DateTime?\n\n  /// Status ikatan kerja. Dipakai rule payroll untuk menegakkan aturan\n  /// manajemen \"yang masih belum di kontrak belum bisa mendapatkan bonus\n  /// tambahan\" — tanpa kolom ini aturan itu tidak punya data untuk dicek.\n  /// Default sengaja BELUM_KONTRAK: menganggap karyawan sudah berkontrak\n  /// padahal belum berarti membayar bonus yang tidak berhak.\n  employmentStatus  EmploymentStatus @default(BELUM_KONTRAK)\n  /// Tanggal mulai kontrak yang sedang berjalan. Null untuk BELUM_KONTRAK.\n  contractStartDate DateTime?\n  /// Tanggal berakhir kontrak. Null berarti tidak berbatas waktu — benar untuk\n  /// PKWTT, dan pada PKWT berarti tanggal habisnya belum diisi.\n  contractEndDate   DateTime?\n\n  isActive             Boolean               @default(true)\n  customRoleId         String?\n  kpiEntries           KpiEntry[]            @relation(\"KpiEntryEmployee\")\n  kpiEntriesCreated    KpiEntry[]            @relation(\"KpiEntryCreatedBy\")\n  kpiEntriesReviewed   KpiEntry[]            @relation(\"KpiEntryReviewedBy\")\n  kpiPeriods           KpiPeriod[]           @relation(\"KpiPeriodEmployee\")\n  kpiPeriodsLocked     KpiPeriod[]           @relation(\"KpiPeriodLockedBy\")\n  kpiMonthlyResults    KpiMonthlyResult[]\n  salaryComponents     UserSalaryComponent[]\n  attendances          Attendance[]          @relation(\"AttendanceEmployee\")\n  attendancesEdited    Attendance[]          @relation(\"AttendanceEditedBy\")\n  payrollSlips         PayrollSlip[]\n  payrollSlipsPaid     PayrollSlip[]         @relation(\"PayrollSlipPaidBy\")\n  payrollRunsGenerated PayrollRun[]          @relation(\"PayrollRunGeneratedBy\")\n  payrollRunsFinalized PayrollRun[]          @relation(\"PayrollRunFinalizedBy\")\n  payrollRulesCreated  PayrollRule[]         @relation(\"PayrollRuleCreatedBy\")\n  samples              Sample[]\n  account              account[]\n  session              session[]\n  branch               Branch?               @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  customRole           custom_role?          @relation(fields: [customRoleId], references: [id])\n\n  @@index([branchId])\n  @@index([customRoleId])\n}\n\nmodel verification {\n  id         String    @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime?\n  updatedAt  DateTime?\n}\n\n// ─── Authorization: per-resource, per-PT scope ───────────────────────────────\n// Menggantikan `custom_role.permissions: String[]` yang flat (satu izin = satu\n// string, tanpa dimensi PT). Model ini memisahkan dua hal yang dulu tercampur:\n//\n//   1. RESOURCE  — apa yang boleh diakses (satu halaman + service/API di baliknya)\n//   2. SCOPE     — PT mana saja yang berlaku, terpisah untuk baca dan tulis\n//\n// Karena `custom_role` sudah unique([name, companyId]), \"Role A di PT A\" dan\n// \"Role A di PT B\" adalah dua baris role berbeda — jadi izin per-PT-per-role\n// jatuh keluar dari model ini tanpa kolom tambahan.\n\nenum ScopeMode {\n  /// Tidak punya akses sama sekali. Halaman disembunyikan dari sidebar,\n  /// API mengembalikan 403. Ini juga arti dari \"tidak ada baris sama sekali\".\n  NONE\n  /// Hanya PT milik role itu sendiri (custom_role.companyId).\n  OWN\n  /// Daftar PT eksplisit di kolom *CompanyIds.\n  SELECTED\n  /// Semua PT aktif.\n  ALL\n}\n\nmodel RoleResourcePermission {\n  id       String @id @default(cuid())\n  roleId   String\n  /// Kunci resource dari registry di src/lib/authz/resources.ts.\n  /// Sengaja String, bukan enum DB: menambah halaman baru tidak boleh butuh migrasi.\n  resource String\n\n  viewScope      ScopeMode @default(NONE)\n  /// Hanya dibaca saat viewScope = SELECTED.\n  viewCompanyIds String[]  @default([])\n\n  writeScope      ScopeMode @default(NONE)\n  /// Hanya dibaca saat writeScope = SELECTED.\n  writeCompanyIds String[]  @default([])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  role custom_role @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@unique([roleId, resource])\n  @@index([roleId])\n}\n\nmodel BankAccount {\n  id                String             @id @default(cuid())\n  companyId         String\n  bankName          String\n  accountNumber     String?\n  accountName       String\n  currencyId        String\n  balance           Decimal            @default(0)\n  isActive          Boolean            @default(true)\n  sortOrder         Int                @default(0)\n  note              String?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  company           Company            @relation(fields: [companyId], references: [id])\n  currency          Currency           @relation(fields: [currencyId], references: [id])\n  mutations         BankMutation[]\n  dailyEntries      DailyBankEntry[]\n  valasTransactions ValasTransaction[]\n\n  @@index([companyId])\n}\n\nmodel BankMutation {\n  id            String           @id @default(cuid())\n  bankAccountId String\n  type          BankMutationType\n  amount        Decimal\n  balanceAfter  Decimal\n  description   String?\n  createdAt     DateTime         @default(now())\n  createdBy     String?\n  bankAccount   BankAccount      @relation(fields: [bankAccountId], references: [id])\n\n  @@index([bankAccountId, createdAt])\n}\n\nmodel DailyBankEntry {\n  id            String            @id @default(cuid())\n  bankAccountId String\n  date          DateTime          @db.Date\n  balance       Decimal           @default(0)\n  note          String?\n  createdBy     String?\n  // Verifikasi H+1: saldo yang diisi hari ini baru bisa dikonfirmasi \"Benar/Beda\" besoknya.\n  // Kalau Beda, angka penggantinya tidak langsung dipakai — masuk CorrectionRequest dulu.\n  verifyStatus  DailyVerifyStatus @default(BELUM_REVIEW)\n  verifyNote    String?\n  verifiedBy    String?\n  verifiedAt    DateTime?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n  bankAccount   BankAccount       @relation(fields: [bankAccountId], references: [id])\n\n  @@unique([bankAccountId, date])\n  @@index([bankAccountId, date])\n}\n\nenum BankMutationType {\n  CREDIT\n  DEBIT\n}\n\nmodel Branch {\n  id                String             @id @default(cuid())\n  name              String\n  address           String?\n  phone             String?\n  isActive          Boolean            @default(true)\n  companyId         String?\n  // Geofence for attendance check-in validation\n  latitude          Float?\n  longitude         Float?\n  attendanceRadiusM Int?               @default(20)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  company           Company?           @relation(fields: [companyId], references: [id])\n  currencyStocks    CurrencyStock[]\n  stockItems        StockItem[]\n  stockMutations    StockMutation[]\n  users             user[]\n  attendances       Attendance[]\n  payrollSlips      PayrollSlip[]\n  valasTransactions ValasTransaction[]\n}\n\nmodel Company {\n  id                        String                          @id @default(cuid())\n  name                      String                          @unique\n  code                      String                          @unique\n  isActive                  Boolean                         @default(true)\n  createdAt                 DateTime                        @default(now())\n  updatedAt                 DateTime                        @updatedAt\n  salaryComponents          SalaryComponent[]\n  branches                  Branch[]\n  roleKpis                  RoleKpi[]\n  custom_roles              custom_role[]\n  stockistPockets           StockistPocket[]\n  kasPockets                KasPocket[]\n  companyStockItems         CompanyStockItem[]\n  bankAccounts              BankAccount[]\n  stockistHeadConfirmations StockistHeadConfirmation[]\n  stockistTotalHeadConfirms StockistTotalHeadConfirmation[]\n  kasHeadConfirmations      KasHeadConfirmation[]\n  bankHeadConfirmations     BankHeadConfirmation[]\n  headConfirmationTotals    CompanyHeadConfirmationTotal[]\n  correctionRequests        CorrectionRequest[]\n  heldFunds                 HeldFund[]\n  payrollRuns               PayrollRun[]\n  valasTransactions         ValasTransaction[]\n}\n\nmodel Currency {\n  id                String             @id @default(cuid())\n  code              String             @unique\n  name              String\n  symbol            String?\n  isActive          Boolean            @default(true)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  bankAccounts      BankAccount[]\n  stocks            CurrencyStock[]\n  stockMutations    StockMutation[]\n  price             CurrencyPrice?\n  valasTransactions ValasTransaction[]\n}\n\n// Harga Valas: harga beli & jual yang benar-benar dipakai Pusat Valas Indo hari\n// ini, diisi manual per mata uang. Beda dengan PriceBenchmark yang menyimpan\n// *aturan* penyesuaian di atas kurs SmartDeal — di sini yang disimpan adalah\n// angka rupiahnya langsung, jadi harga tetap ada meski scraper SmartDeal mati.\n// Global (bukan per cabang/PT), sama seperti PriceBenchmark: satu daftar harga\n// yang berlaku untuk seluruh perusahaan.\nmodel CurrencyPrice {\n  id           String      @id @default(cuid())\n  currencyId   String      @unique\n  // Harga kita MEMBELI valas dari nasabah, dalam IDR per 1 unit mata uang.\n  buyPrice     Decimal     @db.Decimal(18, 4)\n  // Harga kita MENJUAL valas ke nasabah, dalam IDR per 1 unit mata uang.\n  sellPrice    Decimal     @db.Decimal(18, 4)\n  // Dari mana angka yang sekarang berasal. Dipakai UI untuk menandai baris dan\n  // untuk menyusun ringkasan hasil sync.\n  source       PriceSource @default(MANUAL)\n  // Gembok baris. SATU-SATUNYA hal yang melindungi harga dari ditimpa sync —\n  // mengedit manual saja tidak melindungi (lihat currency-price-sync.service).\n  isLocked     Boolean     @default(false)\n  lastSyncedAt DateTime?\n  note         String?\n  updatedBy    String?\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n  currency     Currency    @relation(fields: [currencyId], references: [id], onDelete: Cascade)\n}\n\nenum PriceSource {\n  MANUAL\n  SYNCED\n}\n\n// Saklar auto-sync Harga Valas. Tabel satu baris (`id` selalu \"singleton\"):\n// konsumennya cuma satu dan field-nya jelas, jadi tidak dibuat tabel key-value\n// generik yang nilainya tak bertipe.\nmodel CurrencyPriceSyncSetting {\n  id             String    @id @default(\"singleton\")\n  // Saat true, setiap kurs SmartDeal baru yang masuk langsung disalurkan ke\n  // Harga Valas lewat aturan Patokan Harga.\n  autoSync       Boolean   @default(false)\n  lastRunAt      DateTime?\n  /// Ringkasan sekali jalan, mis. \"24 diperbarui · 3 terkunci · 1 dilewati\".\n  lastRunSummary String?\n  updatedBy      String?\n  updatedAt      DateTime  @updatedAt\n}\n\n// Patokan Harga: manual sell/buy adjustment rules layered on top of the live\n// SmartDeal rate (see watcher-valas.service.ts) to derive Pusat Valas Indo's\n// own posted rate. Global — not branch/company-scoped. Adjustment strings are\n// stored as-is (e.g. \"+5\", \"-10\", \"c5\", \"f0.05\", \"c0.1+5\") and parsed by\n// src/lib/price-adjustment.ts; this table only persists them.\nmodel PriceBenchmark {\n  id             String   @id @default(cuid())\n  code           String   @unique\n  name           String\n  sellAdjustment String   @default(\"\")\n  buyAdjustment  String   @default(\"\")\n  updatedBy      String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\n// Cache of SmartDeal's live counter rates, refreshed by an external\n// scheduler hitting src/app/api/scrape/smartdeal/route.ts (see also\n// src/lib/smartdeal-scraper.ts). Pages read from here instead of scraping\n// smartdeal.co.id on every request — keeps page loads fast and gives a\n// last-known-good fallback if the scrape fails.\nmodel SmartdealRate {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  buy       Float\n  sell      Float\n  // Value this row held immediately before the current write — lets the UI\n  // show which currencies moved since the last cron fetch. Null until the\n  // second cron run for a code (nothing to compare against on the first).\n  prevBuy   Float?\n  prevSell  Float?\n  fetchedAt DateTime @default(now())\n}\n\n// Health/status of the SmartDeal scrape itself, for Watcher Valas to show\n// whether SmartDeal is currently reachable (\"aktif\"/\"down\") — separate from\n// SmartdealRate, which only ever holds the last-known-good rates and has no\n// notion of a failed attempt. Singleton table (`id` always \"singleton\"), same\n// pattern as CurrencyPriceSyncSetting.\nmodel SmartdealScrapeStatus {\n  id              String    @id @default(\"singleton\")\n  // SmartDeal's own self-reported \"Kurs diperbarui\" timestamp (their\n  // `LIVE_UPDATED` field) from the last successful scrape — distinct from\n  // lastSuccessAt below, which is when WE last scraped successfully.\n  sourceUpdatedAt DateTime?\n  lastAttemptAt   DateTime?\n  lastSuccessAt   DateTime?\n  // Set on the most recent failed attempt, cleared on the next success —\n  // non-null here means SmartDeal is currently considered \"down\".\n  lastError       String?\n  updatedAt       DateTime  @updatedAt\n}\n\n// Stock Management (PT): mata uang & logam mulia yang dimiliki 1 PT (Company) secara\n// langsung — bukan per cabang. Item ditulis manual (nama + kode bebas), terpisah dari\n// module stock lama (StockItem, per-branch) dan dari Stockist (pocket-based).\nmodel CompanyStockItem {\n  id        String               @id @default(cuid())\n  companyId String\n  name      String\n  code      String?\n  type      CompanyStockItemType @default(CURRENCY)\n  sortOrder Int                  @default(0)\n  isActive  Boolean              @default(true)\n  createdAt DateTime             @default(now())\n  updatedAt DateTime             @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  stockistBalances          StockistBalance[]\n  stockistMutations         StockistMutation[]\n  stockistDailyChecks       StockistDailyCheck[]\n  stockistHeadConfirmations StockistHeadConfirmation[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\nenum CompanyStockItemType {\n  CURRENCY\n  LOGAM_MULIA\n}\n\nenum StockItemType {\n  CURRENCY\n  GOLD\n  CASH\n  SILVER\n}\n\n/// Status ikatan kerja karyawan.\n///\n/// Yang membedakan hanya satu hal untuk payroll: sudah terikat kontrak atau\n/// belum. PKWT dan PKWTT dipisah karena masa berlakunya berbeda — PKWT punya\n/// tanggal habis, PKWTT tidak.\nenum EmploymentStatus {\n  /// Belum diikat kontrak apa pun. Tidak berhak atas bonus tambahan.\n  BELUM_KONTRAK\n  /// Masa percobaan. Belum berkontrak, jadi diperlakukan sama seperti di atas.\n  PROBATION\n  /// Perjanjian Kerja Waktu Tertentu — kontrak dengan tanggal habis.\n  PKWT\n  /// Perjanjian Kerja Waktu Tidak Tertentu — karyawan tetap.\n  PKWTT\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// KPI — penilaian kinerja karyawan.\n//\n// Modul ini SENGAJA independen dari payroll: keluarannya hanya SKOR (rasio\n// pencapaian tertimbang, tanpa plafon maupun lantai). Konversi skor menjadi\n// bonus, potongan, atau kewajiban masuk Sabtu ada di rule engine\n// (payroll-rule.prisma), yang membacanya lewat view hv_kpi_monthly.\n//\n// Struktur mengikuti sheet KPI perusahaan (docs/PVI Data/PUSAT KPI SEMUA_.xlsx):\n//   KpiDefinition  = katalog \"Key Results\" beserta cara menilainya\n//   RoleKpi        = penerapan satu KPI ke satu jabatan di satu PT + bobotnya\n//   KpiEntry       = catatan kejadian HARIAN, digulung ke minggu 1-4 lalu bulan\n//   KpiMonthlyResult = hasil akhir bulan yang sudah dibekukan\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// Katalog KPI. Satu definisi bisa dipakai banyak jabatan/PT dengan bobot dan\n/// parameter berbeda — parameter angkanya ada di RoleKpi, bukan di sini.\nmodel KpiDefinition {\n  id          String  @id @default(cuid())\n  /// Slug stabil (mis. \"omzet\", \"complain-nasabah\"). Dipakai seed & integrasi\n  /// modul lain supaya tidak bergantung pada nama yang bisa berubah.\n  code        String  @unique\n  name        String\n  /// Kolom \"Objective\" pada sheet KPI, mis. \"Meningkatkan Pelayanan Kepada Customer\".\n  objective   String?\n  /// Penjelasan aturan mainnya untuk karyawan, mis. \"-3 poin setiap kesalahan hitung\".\n  description String?\n\n  scoringType KpiScoringType\n  unit        KpiUnit        @default(OCCURRENCE)\n  direction   KpiDirection   @default(HIGHER_BETTER)\n\n  // ── Kebijakan pengisian (default; bisa ditimpa per jabatan di RoleKpi) ──\n  /// Siapa yang boleh mencatat. SELF = karyawan sendiri, SUPERVISOR = hanya\n  /// atasan/HR, SYSTEM = diisi otomatis modul lain (tidak bisa diinput manual).\n  defaultInputSource      KpiInputSource @default(SUPERVISOR)\n  /// Entri berstatus PENDING dulu dan baru dihitung setelah atasan menyetujui.\n  defaultRequiresApproval Boolean        @default(true)\n  /// Wajib melampirkan bukti (foto/tautan) saat mencatat.\n  defaultRequiresEvidence Boolean        @default(false)\n\n  /// Kunci kolektor otomatis untuk defaultInputSource = SYSTEM\n  /// (mis. \"OMZET_BRANCH\", \"ATTENDANCE_LATE\"). Null untuk KPI manual.\n  systemSourceKey String?\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  roleKpis RoleKpi[]\n\n  @@index([isActive])\n}\n\n/// Penerapan satu KpiDefinition ke satu jabatan di satu PT: bobot + seluruh\n/// angka penilaiannya. Semua entri KPI menunjuk ke baris ini (bukan ke\n/// definisi), sehingga dua KPI bertipe target pada jabatan yang sama punya\n/// kolam data masing-masing.\nmodel RoleKpi {\n  id           String  @id @default(cuid())\n  companyId    String\n  customRoleId String?\n  kpiId        String\n\n  /// Bobot 0..1. Total seluruh KPI aktif satu jabatan idealnya = 1.\n  weight Decimal @default(0)\n\n  // ── Parameter penilaian (yang dipakai tergantung scoringType) ──\n  /// TARGET_VALUE & REWARD_POINT: nilai/poin yang harus dicapai sebulan.\n  targetValue    Decimal?\n  /// PENALTY_POINT & TOLERANCE_LIMIT: poin awal sebelum dikurangi (default 100).\n  basePoint      Decimal?           @default(100)\n  /// Poin (atau persen untuk PENALTY_PERCENT) per satu kejadian.\n  pointPerUnit   Decimal?\n  /// TOLERANCE_LIMIT: ambang yang masih ditoleransi, mis. selisih kas 100.000.\n  toleranceLimit Decimal?\n  /// Cakupan perhitungan toleransi.\n  toleranceScope KpiToleranceScope? @default(DAILY)\n\n  // ── Override kebijakan pengisian (null = ikut KpiDefinition) ──\n  inputSource      KpiInputSource?\n  requiresApproval Boolean?\n  requiresEvidence Boolean?\n\n  /// Parameter kolektor otomatis, dipakai hanya bila definisinya bersumber\n  /// SYSTEM. Bentuknya berbeda tiap systemSourceKey — lihat\n  /// src/lib/kpi-collectors.ts. Contoh untuk ATTENDANCE_CLOSING:\n  /// `{ \"deadline\": \"05:15\", \"graceMinutes\": 60 }`. Disimpan per jabatan\n  /// karena batas jam closing berbeda antar PT (PVI 05.15, PTU 05.00).\n  systemConfig Json?\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company    Company       @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  customRole custom_role?  @relation(fields: [customRoleId], references: [id])\n  definition KpiDefinition @relation(fields: [kpiId], references: [id], onDelete: Cascade)\n  entries    KpiEntry[]\n\n  @@unique([companyId, customRoleId, kpiId])\n  @@index([companyId, customRoleId])\n}\n\n/// Satu catatan kejadian KPI pada satu TANGGAL. Semua tipe penilaian memakai\n/// tabel ini: `quantity` berarti jumlah kejadian (penalti/reward), nilai rupiah\n/// (omzet), atau besaran selisih (toleransi kas) sesuai unit definisinya.\n/// Menggantikan KpiLog + Revenue yang lama.\nmodel KpiEntry {\n  id         String @id @default(cuid())\n  employeeId String\n  roleKpiId  String\n\n  /// Tanggal kejadian sebenarnya — bukan tanggal input. Periode & minggu\n  /// diturunkan darinya saat menyimpan agar bisa difilter tanpa hitung ulang.\n  occurredAt  DateTime @db.Date\n  periodYear  Int\n  periodMonth Int\n  /// Minggu ke-1..5 dalam bulan (mengikuti kolom \"week 1-4\" di sheet KPI).\n  weekOfMonth Int\n\n  quantity    Decimal\n  note        String?\n  evidenceUrl String?\n\n  source KpiInputSource\n  /// PENDING hanya terjadi bila KPI-nya menuntut persetujuan; entri dari\n  /// atasan/sistem langsung APPROVED. Hanya APPROVED yang masuk perhitungan.\n  status KpiEntryStatus @default(APPROVED)\n\n  /// Null berarti entri dihasilkan kolektor otomatis — tidak ada manusia yang\n  /// mencatatnya, dan mengarang penulis akan merusak jejak audit.\n  createdById  String?\n  reviewedById String?\n  reviewedAt   DateTime?\n  reviewNote   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  employee   user    @relation(\"KpiEntryEmployee\", fields: [employeeId], references: [id], onDelete: Cascade)\n  createdBy  user?   @relation(\"KpiEntryCreatedBy\", fields: [createdById], references: [id])\n  reviewedBy user?   @relation(\"KpiEntryReviewedBy\", fields: [reviewedById], references: [id])\n  roleKpi    RoleKpi @relation(fields: [roleKpiId], references: [id], onDelete: Cascade)\n\n  @@index([employeeId, periodYear, periodMonth])\n  @@index([roleKpiId, periodYear, periodMonth])\n  @@index([status, employeeId])\n  @@index([occurredAt])\n}\n\n/// Status periode penilaian per karyawan. Setelah LOCKED, entri periode itu\n/// tidak bisa ditambah/diubah/dihapus sehingga skor yang sudah dipakai payroll\n/// tidak berubah di belakang layar.\nmodel KpiPeriod {\n  id         String          @id @default(cuid())\n  employeeId String\n  month      Int\n  year       Int\n  status     KpiPeriodStatus @default(OPEN)\n  lockedAt   DateTime?\n  lockedById String?\n  note       String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  employee user  @relation(\"KpiPeriodEmployee\", fields: [employeeId], references: [id], onDelete: Cascade)\n  lockedBy user? @relation(\"KpiPeriodLockedBy\", fields: [lockedById], references: [id])\n\n  @@unique([employeeId, month, year])\n  @@index([year, month, status])\n}\n\n/// Hasil perhitungan sebulan. Tidak menyimpan nominal bonus/denda — itu urusan\n/// payroll. `totalScore` adalah rasio tertimbang (1 = 100% target tercapai).\nmodel KpiMonthlyResult {\n  id            String   @id @default(cuid())\n  employeeId    String\n  month         Int\n  year          Int\n  totalScore    Decimal\n  /// A/B/C/D hasil pemetaan totalScore, disimpan agar riwayat tidak berubah\n  /// kalau ambang grade suatu saat disetel ulang.\n  grade         String   @default(\"D\")\n  breakdownJson Json\n  calculatedAt  DateTime @default(now())\n\n  employee user @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n\n  @@unique([employeeId, month, year])\n  @@index([employeeId, year, month])\n}\n\n/// Cara sebuah KPI dinilai. Setiap varian punya rumusnya sendiri di\n/// src/lib/kpi-scoring.ts.\nenum KpiScoringType {\n  /// Realisasi dibagi target. Untuk omzet, net profit margin, jumlah briefing.\n  TARGET_VALUE\n  /// Mulai dari basePoint, tiap kejadian mengurangi pointPerUnit.\n  /// Mis. \"-3 poin setiap kesalahan hitung\".\n  PENALTY_POINT\n  /// Mulai dari 0, tiap kejadian menambah pointPerUnit, dibagi targetValue.\n  /// Mis. \"1 Google review = +2 poin, target 50 poin\".\n  REWARD_POINT\n  /// Mulai 100%, tiap kejadian memotong pointPerUnit persen.\n  /// Mis. \"-5% setiap kali telat update kurs\".\n  PENALTY_PERCENT\n  /// Ada ambang yang ditoleransi per hari/minggu/bulan; yang melampaui kena\n  /// pointPerUnit. Mis. \"selisih kas maks 100rb/hari, lebih dari itu -4 poin\".\n  TOLERANCE_LIMIT\n  /// Rasio hari patuh terhadap hari tercatat. Untuk checklist harian\n  /// (quantity 1 = patuh, 0 = tidak).\n  BOOLEAN_DAILY\n}\n\nenum KpiUnit {\n  OCCURRENCE\n  CURRENCY\n  POINT\n  PERCENT\n  DAY\n  PERSON\n}\n\nenum KpiDirection {\n  HIGHER_BETTER\n  LOWER_BETTER\n}\n\nenum KpiInputSource {\n  SELF\n  SUPERVISOR\n  SYSTEM\n}\n\nenum KpiEntryStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum KpiPeriodStatus {\n  OPEN\n  LOCKED\n}\n\nenum KpiToleranceScope {\n  DAILY\n  WEEKLY\n  MONTHLY\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// RULE REWARD & DENDA — definisi aturan slip gaji.\n//\n// Spesifikasi: docs/tasks/spesifikasi-rule-slip-gaji.md\n// Hasil eksekusinya: payroll-run.prisma (PayrollRun / PayrollSlip / …Entry)\n//\n// Empat hal menentukan bentuk tabel ini, dan keempatnya disengaja:\n//\n// 0. ARAH UANG MILIK KONDISI, BUKAN MILIK RULE. Sebuah rule TIDAK punya tipe\n//    \"bonus\" atau \"denda\". Yang menentukan menambah atau mengurangi adalah\n//    TANDA nominal pada tier/guard yang cocok: positif menambah gaji, negatif\n//    menguranginya. Satu rule karena itu bisa memberi bonus pada skor tinggi\n//    DAN menjatuhkan potongan pada skor rendah — persis seperti sheet\n//    manajemen menuliskannya dalam satu tabel.\n//\n//    Sebelumnya arah ditentukan kolom `type` di tingkat rule, sehingga tiap\n//    jabatan butuh SEPASANG rule (bonus_kpi_* dan denda_kpi_*) yang menyalin\n//    SQL, guard, dan sasaran yang sama persis — dua tempat yang harus diubah\n//    bersamaan setiap kali satu band bergeser. Kolom itu dibuang pada migrasi\n//    20260805040000.\n//\n// 1. APPEND-ONLY. Mengubah rule TIDAK pernah `UPDATE` — ia membuat baris baru\n//    dengan `version` naik, dan mengisi `effectiveTo` pada versi lama. Slip\n//    yang sudah dibayar merujuk `ruleKey@version`, jadi baris lama harus tetap\n//    utuh apa adanya. Inilah pengganti riwayat git saat rule pindah dari file\n//    ke database.\n//\n// 2. DITANDATANGANI. `signature` adalah HMAC-SHA256 atas seluruh isi rule —\n//    termasuk tier-nya. Baris yang disunting langsung lewat klien SQL akan\n//    gagal verifikasi dan DITOLAK engine, bukan dijalankan diam-diam. Yang\n//    dilindungi di sini integritas, bukan kerahasiaan: isi rule memang\n//    ditampilkan di halaman Rule.\n//\n// 3. SQL TERPISAH DARI KEBIJAKAN. `sql` hanya boleh disunting pemegang\n//    capability `payroll.rules.sql`; tier, nominal, sasaran, dan masa berlaku\n//    boleh disunting pemegang `payroll.rules`. Pembagiannya mengikuti siapa\n//    yang berhak: SQL menentukan APA yang diukur, tier menentukan BERAPA\n//    harganya.\n//\n// Query rule dijalankan lewat koneksi read-only (DATABASE_VIEW_ONLY_URL) yang\n// hanya bisa SELECT dari view hv_*. Batas itu ditegakkan database, bukan\n// sekadar validator di aplikasi.\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// Satu VERSI dari sebuah rule. Baris tidak pernah diubah setelah dibuat.\nmodel PayrollRule {\n  id String @id @default(cuid())\n\n  /// Identitas rule yang stabil sepanjang umurnya — TIDAK berubah saat versi\n  /// naik. Inilah yang tersimpan di PayrollSlipEntry.ruleId.\n  ruleKey String\n  /// Naik setiap kali isi rule berubah. Ikut tersimpan di entri hasil.\n  version Int\n\n  /// Masa berlaku, keduanya INKLUSIF. Engine memilih versi yang berlaku pada\n  /// periode yang dihitung; `effectiveTo` null berarti masih berlaku.\n  ///\n  /// Dua versi dengan `ruleKey` sama TIDAK BOLEH beririsan — kalau beririsan,\n  /// engine tidak punya jawaban tunggal untuk \"rule mana yang berlaku bulan\n  /// ini\". Itu ditegakkan DATABASE lewat constraint EXCLUDE\n  /// `payroll_rule_no_overlap` (migrasi 20260805020000), bukan hanya oleh\n  /// pemeriksaan aplikasi: pemeriksaan aplikasi bisa dilewati lewat klien SQL,\n  /// impor, atau dua permintaan yang berjalan bersamaan. Prisma belum bisa\n  /// menyatakan constraint EXCLUDE, jadi ia hidup di SQL migrasi — jangan\n  /// dihapus saat schema ini di-regenerate.\n  effectiveFrom DateTime  @db.Date\n  effectiveTo   DateTime? @db.Date\n\n  mode PayrollRuleMode\n\n  /// Query pengumpul data. Hanya SELECT, hanya dari view `hv_*`.\n  sql       String\n  /// Kolom hasil query yang dipakai mencocokkan tier.\n  tierField String\n\n  /// Angka bernama yang dipakai formula: `{ \"hari_kerja_standar\": 24 }`.\n  constants Json?\n  /// Kondisi bebas yang dinilai SEBELUM tier, berurutan; yang pertama cocok\n  /// menang dan menghentikan sisanya. Dua aksi:\n  ///\n  ///   • `skip`     — batalkan rule, tidak ada uang, catat alasannya:\n  ///     `{ \"if\": \"hari_tercatat == 0\", \"aksi\": \"skip\", \"flag\": \"data_kosong\" }`\n  ///   • `terapkan` — langsung bayarkan/potong tanpa melihat tier:\n  ///     `{ \"if\": \"berkontrak == 0\", \"aksi\": \"terapkan\", \"nominal\": -50000,\n  ///        \"label\": \"...\", \"flag\": \"belum_berkontrak\" }`\n  ///\n  /// `terapkan` memakai `nominal` ATAU `formula` (tepat satu), dan tandanya\n  /// menentukan arah sama seperti pada tier. Ia ada karena tier hanya bisa\n  /// mencocokkan RENTANG pada satu kolom; kondisi yang menyangkut kolom lain\n  /// — atau menggabungkan beberapa kolom — tidak bisa dinyatakan sebagai tier.\n  guards    Json?\n  /// Dipakai kalau tidak ada tier yang cocok. Wajib ada — engine tidak boleh\n  /// kehabisan jawaban di tengah perhitungan gaji.\n  defaults  Json\n  /// Sasaran rule (`for`): array grup `{ company, branch, roles }`.\n  targets   Json\n  /// Pengecualian (`except`). Selalu menang atas `targets`.\n  excepts   Json?\n\n  /// Keterangan untuk manusia — dasar kebijakan, sumber sheet, dst.\n  note       String?\n  /// Alasan perubahan pada versi INI. Bersama `version` inilah jejak yang\n  /// menggantikan pesan commit.\n  changeNote String?\n\n  /// HMAC-SHA256 atas bentuk kanonik rule + tier-nya, memakai\n  /// PAYROLL_RULE_SIGNING_KEY. Tidak cocok = rule ditolak.\n  signature String\n\n  createdAt   DateTime @default(now())\n  createdById String?\n\n  /// Versi yang digantikan baris ini. Rantai ini yang membuat \"siapa mengubah\n  /// apa, kapan\" bisa ditelusuri tanpa tabel audit terpisah.\n  supersedesId String? @unique\n\n  createdBy    user?             @relation(\"PayrollRuleCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  supersedes   PayrollRule?      @relation(\"PayrollRuleVersion\", fields: [supersedesId], references: [id], onDelete: SetNull)\n  supersededBy PayrollRule?      @relation(\"PayrollRuleVersion\")\n  tiers        PayrollRuleTier[]\n\n  @@unique([ruleKey, version])\n  @@index([ruleKey])\n  @@index([effectiveFrom, effectiveTo])\n}\n\n/// Satu baris tier: rentang nilai → nominal, per_unit, atau formula.\n///\n/// Tabel tersendiri (bukan Json di dalam PayrollRule) karena inilah bagian\n/// yang paling sering disunting manusia lewat UI — bentuknya perlu ditegakkan\n/// database, bukan dipercayakan pada isi kolom Json.\nmodel PayrollRuleTier {\n  id     String @id @default(cuid())\n  ruleId String\n\n  /// Urutan tampil. Pencocokan tetap memakai min/max, bukan urutan ini —\n  /// validator sudah menjamin tier tidak tumpang tindih.\n  sortOrder Int\n\n  /// Batas bawah & atas, keduanya INKLUSIF. Null = tidak terbatas di sisi itu.\n  min Decimal?\n  max Decimal?\n\n  /// Tepat SATU dari ketiganya yang boleh terisi.\n  ///\n  /// BERTANDA. Positif menambah gaji, negatif menguranginya — inilah satu-\n  /// satunya yang menentukan arah, dan berlaku untuk ketiganya (`formula` yang\n  /// menghasilkan angka negatif juga mengurangi). Nol berarti tier itu memang\n  /// tidak berdampak pada gaji, dan tetap ditulis sebagai tier supaya slip bisa\n  /// menyatakan \"skor Anda di zona aman\" alih-alih diam.\n  nominal Decimal?\n  perUnit Decimal?\n  formula String?\n\n  /// Kolom hasil query yang dikalikan `perUnit`. Wajib menyertai perUnit.\n  unitField String?\n\n  /// Alasan yang tampil di slip gaji. Disalin apa adanya ke\n  /// PayrollSlipEntry.label supaya angka dan alasannya tidak pernah berbeda.\n  label String\n\n  // ── Sanksi non-uang ──────────────────────────────────────────────────────\n  //\n  // Sebagian konsekuensi di sheet manajemen bukan rupiah: \"setiap Sabtu wajib\n  // masuk\", \"pemotongan 300 rb dan sp\". Kalau tidak diwakili di sini, satu-\n  // satunya jejaknya adalah teks pada `label` — tidak bisa difilter, tidak\n  // bisa dilaporkan, dan hilang begitu labelnya diedit.\n  //\n  // Keduanya TIDAK memengaruhi nominal; ia menyertai tier yang cocok.\n\n  /// Tier ini mewajibkan karyawan masuk setiap Sabtu selama periode berikutnya.\n  mandatorySaturday Boolean @default(false)\n  /// Tier ini disertai Surat Peringatan.\n  warningLetter     Boolean @default(false)\n\n  rule PayrollRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)\n\n  @@unique([ruleId, sortOrder])\n  @@index([ruleId])\n}\n\nenum PayrollRuleMode {\n  /// Query mengembalikan satu baris; tier dicocokkan sekali.\n  AGREGAT\n  /// Query mengembalikan banyak baris; tiap baris dinilai lalu dijumlahkan.\n  PER_BARIS\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// PAYROLL RUN — hasil eksekusi rule engine slip gaji.\n//\n// Spesifikasi rule: docs/tasks/spesifikasi-rule-slip-gaji.md\n// Rule-nya sendiri TIDAK disimpan di sini — rule hidup sebagai file .json di\n// prisma/seeds/payroll-rules/ supaya setiap perubahan kebijakan gaji melewati review\n// kode dan tercatat di git. Yang disimpan di database hanya hasilnya.\n//\n// Prinsip yang menentukan bentuk tabel ini: slip harus bisa menjelaskan dirinya\n// sendiri bertahun-tahun kemudian, tanpa perlu menjalankan ulang perhitungan.\n// Karena itu setiap entri membawa `inputs` — nilai-nilai yang dipakai engine\n// saat itu — bukan sekadar angka akhirnya.\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// Satu eksekusi payroll untuk satu PT pada satu periode.\n///\n/// Boleh ada lebih dari satu run untuk periode yang sama: generate ulang\n/// membuat run baru, tidak menimpa yang lama. `attempt` membedakannya. Run lama\n/// tetap utuh supaya slip yang sudah dibayar masih bisa ditunjukkan apa adanya,\n/// meskipun data sumbernya sudah berubah sejak itu.\nmodel PayrollRun {\n  id        String @id @default(cuid())\n  companyId String\n\n  /// Periode gaji. Disimpan sebagai rentang tanggal, bukan sekadar bulan,\n  /// supaya periode gaji yang tidak mengikuti kalender (mis. 26–25) tetap bisa\n  /// diwakili. `periodMonth`/`periodYear` ikut disimpan untuk pencarian.\n  periodStart DateTime @db.Date\n  periodEnd   DateTime @db.Date\n  periodMonth Int\n  periodYear  Int\n\n  /// Nomor percobaan untuk periode yang sama. 1 = generate pertama.\n  attempt Int @default(1)\n\n  status PayrollRunStatus @default(DRAFT)\n\n  /// Ringkasan konfigurasi yang dipakai run ini: daftar `id@versi` rule yang\n  /// dievaluasi, plus hash isi file. Tanpa ini, dua run dengan angka berbeda\n  /// tidak bisa dibedakan antara \"datanya berubah\" dan \"rule-nya berubah\".\n  rulesetHash    String?\n  rulesetVersion Json?\n\n  generatedAt   DateTime  @default(now())\n  generatedById String?\n  finalizedAt   DateTime?\n  finalizedById String?\n  /// Terisi saat run ditandai dibayar. Setelah ini isi run tidak boleh diubah.\n  paidAt        DateTime?\n\n  note String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company     Company       @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  generatedBy user?         @relation(\"PayrollRunGeneratedBy\", fields: [generatedById], references: [id], onDelete: SetNull)\n  finalizedBy user?         @relation(\"PayrollRunFinalizedBy\", fields: [finalizedById], references: [id], onDelete: SetNull)\n  slips       PayrollSlip[]\n\n  @@unique([companyId, periodYear, periodMonth, attempt])\n  @@index([companyId, periodYear, periodMonth])\n  @@index([status])\n}\n\nenum PayrollRunStatus {\n  /// Baru di-generate, masih boleh dihapus dan digenerate ulang.\n  DRAFT\n  /// Sudah diperiksa HR, angkanya dianggap benar.\n  FINALIZED\n  /// Sudah dibayar. Tidak boleh diubah lagi.\n  PAID\n  /// Dibatalkan — digantikan run lain untuk periode yang sama.\n  VOID\n}\n\n/// Slip satu karyawan dalam satu run.\n///\n/// Semua kolom nominal adalah SNAPSHOT saat run dibuat. Kalau gaji pokok\n/// karyawan naik bulan depan, slip bulan ini tidak ikut berubah.\nmodel PayrollSlip {\n  id     String @id @default(cuid())\n  runId  String\n  userId String\n\n  /// Penempatan karyawan saat run dibuat — dipakai untuk pengelompokan laporan\n  /// dan tetap benar walaupun karyawan pindah cabang setelahnya.\n  branchId     String?\n  customRoleId String?\n\n  // ── Komponen tetap (snapshot dari data karyawan) ────────────────────────\n  baseSalary         Decimal @default(0)\n  mealAllowance      Decimal @default(0)\n  transportAllowance Decimal @default(0)\n  positionAllowance  Decimal @default(0)\n  bpjsKesehatan      Decimal @default(0)\n\n  // ── Ringkasan hasil rule ────────────────────────────────────────────────\n  /// Total entri bertipe BONUS. Bisa negatif (bonus yang hangus sebagian).\n  totalBonus     Decimal @default(0)\n  /// Total entri bertipe DENDA. Disimpan positif.\n  totalPenalty   Decimal @default(0)\n  /// Total entri bertipe POTONGAN ditambah komponen gaji bertipe DEDUCTION.\n  totalDeduction Decimal @default(0)\n  /// Total komponen gaji tambahan bertipe ALLOWANCE.\n  totalAllowance Decimal @default(0)\n\n  grossPay Decimal @default(0)\n  netPay   Decimal @default(0)\n\n  /// Ada entri berstatus SKIPPED atau berflag di slip ini — perlu dilihat\n  /// manusia sebelum difinalkan. Diturunkan dari entri, disimpan supaya daftar\n  /// slip bisa menyaring tanpa menghitung ulang.\n  needsReview Boolean @default(false)\n\n  note String?\n\n  /// Terisi saat slip INI ditandai dibayar — baik lewat \"Bayar\" per orang\n  /// maupun ikut terbawa saat seluruh run dibayar sekaligus. Berbeda dari\n  /// PayrollRun.paidAt: run baru berstatus PAID setelah SEMUA slipnya\n  /// terbayar, sehingga karyawan bisa dibayar satu-satu tanpa menunggu yang\n  /// lain.\n  paidAt   DateTime?\n  paidById String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  run        PayrollRun         @relation(fields: [runId], references: [id], onDelete: Cascade)\n  user       user               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branch     Branch?            @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  customRole custom_role?       @relation(fields: [customRoleId], references: [id], onDelete: SetNull)\n  paidBy     user?              @relation(\"PayrollSlipPaidBy\", fields: [paidById], references: [id], onDelete: SetNull)\n  entries    PayrollSlipEntry[]\n\n  @@unique([runId, userId])\n  @@index([paidAt])\n  @@index([runId])\n  @@index([userId])\n  @@index([branchId])\n  @@index([needsReview])\n}\n\n/// Satu baris alasan di slip: satu rule yang dievaluasi, atau satu komponen\n/// gaji tetap. Inilah yang tampil ke karyawan sebagai rincian.\n///\n/// Entri juga dibuat untuk rule yang TIDAK menghasilkan uang (status SKIPPED).\n/// Slip harus bisa menjelaskan kenapa sebuah rule tidak jalan, bukan diam saja.\nmodel PayrollSlipEntry {\n  id     String @id @default(cuid())\n  slipId String\n\n  source PayrollEntrySource\n  type   PayrollEntryType\n  status PayrollEntryStatus @default(APPLIED)\n\n  /// `id` rule dari file .json. Null untuk entri komponen gaji tetap.\n  ruleId            String?\n  /// `versi` rule saat run dijalankan. Bersama ruleId inilah kunci untuk\n  /// menemukan kembali definisi rule di git.\n  ruleVersion       Int?\n  /// Komponen gaji tetap yang menjadi sumber entri, kalau source = COMPONENT.\n  salaryComponentId String?\n\n  /// Tier yang cocok, mis. \"min:23\" atau \"min:1,max:3\". Null kalau memakai\n  /// `default` atau kalau rule di-skip.\n  tier  String?\n  /// Alasan yang tampil di slip. Disalin dari `label` tier — tidak pernah\n  /// disusun ulang di sisi tampilan, supaya angka dan alasan tidak bisa\n  /// berbeda.\n  label String\n\n  /// Selalu ditandatangani sesuai arah aslinya: bonus positif, denda dan\n  /// potongan negatif. Ringkasan di PayrollSlip yang menormalkannya.\n  amount Decimal @default(0)\n\n  /// Semua nilai yang dipakai untuk sampai ke `amount`: kolom hasil query,\n  /// konstanta rule, dan field karyawan yang dirujuk formula. Ini yang membuat\n  /// slip menjelaskan dirinya sendiri, dan yang membuat generate ulang bisa\n  /// dibandingkan dengan yang sudah dibayar.\n  inputs    Json?\n  /// Rincian per kejadian untuk rule mode per_baris (tanggal, tier, nominal).\n  breakdown Json?\n  /// Formula yang dievaluasi, apa adanya — supaya bisa dibaca tanpa membuka\n  /// file rule. Null kalau tier memakai nominal tetap.\n  formula   String?\n\n  /// Penanda dari guard atau default, mis. \"data_kosong\", \"butuh_review\".\n  flag String?\n\n  createdAt DateTime @default(now())\n\n  slip            PayrollSlip      @relation(fields: [slipId], references: [id], onDelete: Cascade)\n  salaryComponent SalaryComponent? @relation(fields: [salaryComponentId], references: [id], onDelete: SetNull)\n\n  @@index([slipId])\n  @@index([ruleId])\n  @@index([status])\n}\n\nenum PayrollEntrySource {\n  /// Dihasilkan rule engine dari tabel PayrollRule.\n  RULE\n  /// Komponen gaji tetap dari UserSalaryComponent.\n  COMPONENT\n  /// Dihitung langsung oleh payroll.service, di luar rule engine — saat ini\n  /// hanya potongan ketidakhadiran (sakit/izin/alpha). Dibedakan dari MANUAL\n  /// karena tidak ada manusia yang memutuskannya, dan dari RULE karena tidak\n  /// punya `ruleId` yang bisa ditelusuri ke tabel PayrollRule. Begitu potongan\n  /// itu dipindahkan menjadi rule — seperti yang sudah dilakukan pada denda\n  /// keterlambatan — sumber ini tidak akan dipakai lagi.\n  SISTEM\n  /// Penyesuaian manual oleh HR, dengan alasan tertulis di `label`.\n  MANUAL\n}\n\nenum PayrollEntryType {\n  BONUS\n  DENDA\n  POTONGAN\n  TUNJANGAN\n}\n\nenum PayrollEntryStatus {\n  /// Nominalnya ikut dihitung.\n  APPLIED\n  /// Guard kena — rule tidak menghasilkan uang, tapi tetap dicatat beserta\n  /// alasannya dan masuk antrian review.\n  SKIPPED\n  /// Query atau formula gagal dievaluasi. Sama seperti SKIPPED tidak\n  /// menghasilkan uang, tapi ini menandakan konfigurasi yang perlu diperbaiki,\n  /// bukan data karyawan yang belum lengkap.\n  ERROR\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// PAYROLL — komponen gaji tambahan.\n//\n// Dipisah dari kpi.prisma dengan sengaja: modul KPI hanya menilai kinerja,\n// keputusan bonus/potongan sepenuhnya milik payroll.\n//\n// Konversi skor KPI menjadi rupiah SELURUHNYA ada di rule engine\n// (payroll-rule.prisma). Matriks insentif lama (BonusMatrix, lalu\n// PayrollIncentiveMatrix) sudah DIBUANG seluruhnya, termasuk dari riwayat\n// migrasi: terlalu kaku (tier hanya bisa berpatokan pada skor KPI, nominalnya\n// selalu angka tetap, sasarannya terkunci pada satu jabatan di satu PT) dan,\n// selama masih hidup berdampingan dengan rule engine, hasil keduanya ikut\n// dijumlahkan sehingga karyawan dibayar dua kali untuk skor yang sama.\n//\n// Data payroll hasil perhitungan versi lama juga dikosongkan pada migrasi\n// 20260805030000 — periode gaji digenerate ulang lewat rule engine, tidak\n// dikonversi.\n//\n// Yang tersisa di berkas ini hanya komponen gaji yang nominalnya tetap per\n// bulan dan tidak bergantung pada kinerja.\n// ═══════════════════════════════════════════════════════════════════════════\n\n// ───────────────────────────────────────────────────────────────────────────\n// KOMPONEN GAJI TAMBAHAN\n//\n// Uang makan, transport, jabatan, dan BPJS TIDAK LAGI kolom tetap di `user`\n// (migrasi 20260806000000) — sekarang cuma 4 SalaryComponent global biasa,\n// sama seperti tunjangan pulsa, komunikasi, kacamata, potongan koperasi, dst.\n// Dicocokkan oleh `payrollService`/`loadEmployeeContext` lewat NAMA\n// (\"Uang Makan\", \"Uang Transport\", \"Uang Jabatan\", \"BPJS Kesehatan\"), bukan id\n// tetap — supaya menambah/mengubah jenis tunjangan/potongan tidak perlu\n// migrasi schema lagi, dengan trade-off: rename nama komponen itu lewat\n// halaman Komponen Gaji akan melepas pencocokannya.\n//\n// Semuanya nominal TETAP PER BULAN. Tidak ada perhitungan pro-rata per hari\n// hadir.\n// ───────────────────────────────────────────────────────────────────────────\n\n/// Daftar induk komponen gaji. `companyId` null = berlaku untuk semua PT.\nmodel SalaryComponent {\n  id            String              @id @default(cuid())\n  companyId     String?\n  name          String\n  kind          SalaryComponentKind\n  /// Nilai yang diusulkan saat komponen dipasang ke karyawan baru; nilai\n  /// sesungguhnya selalu diambil dari UserSalaryComponent.amount.\n  defaultAmount Decimal?\n  note          String?\n  isActive      Boolean             @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company     Company?              @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  assignments UserSalaryComponent[]\n  slipEntries PayrollSlipEntry[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\n/// Nilai komponen untuk satu karyawan. Tanpa baris ini komponen tidak ikut\n/// dihitung, jadi daftar induk boleh berisi komponen yang belum dipakai.\nmodel UserSalaryComponent {\n  id          String  @id @default(cuid())\n  userId      String\n  componentId String\n  /// Selalu positif — arah (tambah/potong) ditentukan `component.kind`.\n  amount      Decimal\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user      user            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  component SalaryComponent @relation(fields: [componentId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, componentId])\n  @@index([userId])\n  @@index([componentId])\n}\n\nenum SalaryComponentKind {\n  /// Menambah gaji kotor (mis. tunjangan pulsa, alokasi BPJS tambahan).\n  ALLOWANCE\n  /// Mengurangi gaji diterima (mis. potongan koperasi, cicilan seragam).\n  DEDUCTION\n}\n\n// Dana Tertahan (hutang orang ke perusahaan) — piutang harian per PT.\n//\n// Bentuknya sengaja BEDA dari DailyBankEntry / KasDailyEntry. Dua model itu satu\n// baris per pocket per tanggal, sehingga punya `@@unique([pocketId, date])` dan\n// selalu ada barisnya. Di sini tiap tanggal dimulai kosong dan barisnya ditambah\n// sebanyak yang memang terjadi — jadi tidak ada kunci unik per tanggal, dan\n// \"tidak ada baris\" adalah kondisi normal, bukan \"belum diisi\".\n//\n// Statusnya BERTAHAN melintasi tanggal: baris yang dicatat hari Senin tetap\n// terhitung tertahan sampai ada yang menyatakannya lunas, mungkin seminggu\n// kemudian. Karena itu total dana tertahan dijumlahkan dari SELURUH tanggal yang\n// belum lunas, bukan dari tanggal yang sedang dibuka di halaman.\nmodel HeldFund {\n  id        String   @id @default(cuid())\n  companyId String\n  // Tanggal hutangnya tercatat — bukan tanggal jatuh tempo. Inilah tanggal yang\n  // dinavigasi di halaman Dana Tertahan.\n  date      DateTime @db.Date\n  name      String // nama orang/pihak yang uangnya belum masuk\n  amount    Decimal  @default(0)\n  note      String?\n\n  // Pelunasan menandai, tidak menghapus. Baris yang dihapus akan menghilangkan\n  // fakta bahwa dananya pernah tertahan, dan laporan periode lampau justru butuh\n  // fakta itu. `settledAt != null` adalah satu-satunya penanda lunas — sengaja\n  // tanpa boolean terpisah supaya tidak ada dua sumber kebenaran yang bisa beda.\n  settledAt DateTime?\n  settledBy String?\n\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  // Halaman membaca satu PT satu tanggal; laporan membaca yang belum lunas\n  // lintas tanggal. Dua index terpisah karena dua pola baca yang berbeda.\n  @@index([companyId, date])\n  @@index([companyId, settledAt])\n}\n\nenum RefiningMethod {\n  MILLER\n  WOHLWILL\n  AQUA_REGIA\n}\n\nenum RefiningBatchStatus {\n  RUNNING\n  COMPLETED\n  FLAGGED\n}\n\nmodel RefiningBatch {\n  id                String              @id @default(cuid())\n  batchNumber       String              @unique\n  sampleId          String?\n  refiningMethod    RefiningMethod\n  startTimestamp    DateTime            @default(now())\n  estimatedDuration Int?\n  inputWeight       Decimal             @db.Decimal(12, 4)\n  initialPurity     Decimal             @db.Decimal(5, 2)\n  outputWeight      Decimal?            @db.Decimal(12, 4)\n  finalPurity       Decimal?            @db.Decimal(5, 2)\n  recordedYield     Decimal?            @db.Decimal(6, 2)\n  recordedLoss      Decimal?            @db.Decimal(6, 2)\n  status            RefiningBatchStatus @default(RUNNING)\n  notes             String?\n  createdAt         DateTime            @default(now())\n  updatedAt         DateTime            @updatedAt\n\n  sample Sample? @relation(fields: [sampleId], references: [id])\n\n  @@index([status])\n  @@index([startTimestamp])\n  @@index([batchNumber])\n  @@index([sampleId])\n}\n\nenum SampleStatus {\n  RECEIVED\n  IN_PROGRESS\n  COMPLETED\n  REJECTED\n}\n\nenum AssayMethod {\n  FIRE_ASSAY\n  XRF\n  ICP\n}\n\nmodel Sample {\n  id           String       @id @default(cuid())\n  sampleNumber String       @unique\n  materialType String\n  source       String?\n  dateReceived DateTime     @default(now())\n  initialNotes String?\n  status       SampleStatus @default(RECEIVED)\n  technicianId String?\n  method       AssayMethod?\n  assayResults String?\n  completedAt  DateTime?\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  technician      user?           @relation(fields: [technicianId], references: [id])\n  refiningBatches RefiningBatch[]\n\n  @@index([status])\n  @@index([dateReceived])\n  @@index([sampleNumber])\n}\n\nenum ShipmentStatus {\n  PENDING\n  PICKED_UP\n  IN_TRANSIT\n  OUT_FOR_DELIVERY\n  DELIVERED\n  FAILED\n  RETURNED\n  CANCELLED\n}\n\nenum ShipmentProviderCode {\n  JNE\n  TIKI\n  POS_INDONESIA\n  DHL\n  FEDEX\n  CUSTOM\n}\n\nmodel ShipmentProvider {\n  id            String               @id @default(cuid())\n  name          String\n  code          ShipmentProviderCode\n  apiBaseUrl    String?\n  apiKey        String?\n  webhookSecret String?\n  isActive      Boolean              @default(true)\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n\n  shipments Shipment[]\n\n  @@unique([code])\n  @@index([isActive])\n}\n\nmodel Shipment {\n  id                String         @id @default(cuid())\n  trackingNumber    String\n  providerId        String\n  status            ShipmentStatus @default(PENDING)\n  origin            String?\n  destination       String?\n  recipientName     String?\n  recipientPhone    String?\n  // Polymorphic reference: e.g. { referenceType: \"ORDER\", referenceId: \"abc123\" }\n  referenceType     String?\n  referenceId       String?\n  notes             String?\n  estimatedDelivery DateTime?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  provider     ShipmentProvider      @relation(fields: [providerId], references: [id])\n  statusEvents ShipmentStatusEvent[]\n\n  @@unique([trackingNumber, providerId])\n  @@index([providerId])\n  @@index([status])\n  @@index([referenceType, referenceId])\n  @@index([createdAt])\n}\n\nmodel ShipmentStatusEvent {\n  id          String         @id @default(cuid())\n  shipmentId  String\n  status      ShipmentStatus\n  description String?\n  location    String?\n  eventTime   DateTime       @default(now())\n  rawPayload  Json?\n  createdAt   DateTime       @default(now())\n\n  shipment Shipment @relation(fields: [shipmentId], references: [id], onDelete: Cascade)\n\n  @@index([shipmentId, eventTime])\n}\n\nmodel CurrencyStock {\n  id         String   @id @default(cuid())\n  branchId   String?\n  currencyId String\n  quantity   Decimal  @default(0)\n  buyRate    Decimal?\n  sellRate   Decimal?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  branch     Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  currency   Currency @relation(fields: [currencyId], references: [id])\n\n  @@unique([branchId, currencyId])\n}\n\nmodel StockMutation {\n  id         String            @id @default(cuid())\n  branchId   String?\n  currencyId String\n  type       StockMutationType\n  quantity   Decimal\n  rate       Decimal?\n  idrValue   Decimal?\n  note       String?\n  createdAt  DateTime          @default(now())\n  createdBy  String?\n  branch     Branch?           @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  currency   Currency          @relation(fields: [currencyId], references: [id])\n\n  @@index([branchId, currencyId, createdAt])\n}\n\nmodel StockItem {\n  id           String            @id @default(cuid())\n  branchId     String?\n  name         String\n  code         String?\n  type         StockItemType     @default(CURRENCY)\n  sortOrder    Int               @default(0)\n  isActive     Boolean           @default(true)\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n  dailyEntries DailyStockEntry[]\n  branch       Branch?           @relation(fields: [branchId], references: [id], onDelete: SetNull)\n\n  @@unique([branchId, name])\n  @@index([branchId])\n}\n\nmodel DailyStockEntry {\n  id          String    @id @default(cuid())\n  stockItemId String\n  date        DateTime  @db.Date\n  closingQty  Decimal   @default(0)\n  rateIdr     Decimal?\n  totalIdr    Decimal?\n  note        String?\n  createdBy   String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  qty1        Decimal   @default(0)\n  qty2        Decimal   @default(0)\n  stockItem   StockItem @relation(fields: [stockItemId], references: [id])\n\n  @@unique([stockItemId, date])\n  @@index([stockItemId, date])\n}\n\nenum StockMutationType {\n  OPENING\n  BUY\n  SELL\n  TRANSFER_IN\n  TRANSFER_OUT\n  ADJUSTMENT\n}\n\n// Bagian 1 — Stockist (Mata Uang): stock mata uang per pocket, dimiliki 1 PT (Company) dan\n// dipakai bersama oleh semua cabang di bawahnya — bukan per cabang.\nmodel StockistPocket {\n  id        String    @id @default(cuid())\n  companyId String\n  name      String // \"Kas Kecil\", \"Finance Blue\", \"Kurir A\", dst\n  code      String?\n  isDefault Boolean   @default(false) // pocket bawaan yang ikut ke-seed tiap PT baru\n  sortOrder Int       @default(0)\n  isActive  Boolean   @default(true)\n  deletedAt DateTime? // soft delete — pocket Total (isDefault) tidak boleh pernah diisi ini\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  company   Company              @relation(fields: [companyId], references: [id])\n  balances  StockistBalance[]\n  mutations StockistMutation[]\n  checks    StockistDailyCheck[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\nmodel StockistBalance {\n  id                 String   @id @default(cuid())\n  pocketId           String\n  companyStockItemId String\n  quantity           Decimal  @default(0) // saldo berjalan (running balance) — 1 sel di matrix\n  updatedAt          DateTime @updatedAt\n\n  pocket           StockistPocket   @relation(fields: [pocketId], references: [id])\n  companyStockItem CompanyStockItem @relation(fields: [companyStockItemId], references: [id])\n\n  @@unique([pocketId, companyStockItemId])\n  @@index([pocketId])\n}\n\nmodel StockistMutation {\n  id                 String               @id @default(cuid())\n  pocketId           String\n  companyStockItemId String\n  type               StockistMutationType\n  quantity           Decimal // + atau - tergantung type\n  balanceAfter       Decimal\n  note               String?\n  createdAt          DateTime             @default(now())\n  createdBy          String?\n\n  pocket           StockistPocket   @relation(fields: [pocketId], references: [id])\n  companyStockItem CompanyStockItem @relation(fields: [companyStockItemId], references: [id])\n\n  @@index([pocketId, companyStockItemId, createdAt])\n}\n\nmodel StockistDailyCheck {\n  id                 String              @id @default(cuid())\n  pocketId           String\n  companyStockItemId String\n  date               DateTime            @db.Date\n  status             StockistCheckStatus @default(BELUM_REVIEW)\n  enteredQuantity    Decimal? // hasil opname yang diisi user untuk tanggal ini — null = belum diisi\n  filledAt           DateTime? // kapan opname diisi\n  filledBy           String? // siapa yang mengisi opname\n  note               String?\n  reviewedBy         String?\n  reviewedAt         DateTime?\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n\n  pocket           StockistPocket   @relation(fields: [pocketId], references: [id])\n  companyStockItem CompanyStockItem @relation(fields: [companyStockItemId], references: [id])\n\n  @@unique([pocketId, companyStockItemId, date])\n  @@index([pocketId, date])\n  @@index([date, status])\n}\n\nenum StockistMutationType {\n  OPENING\n  TOP_UP\n  WITHDRAWAL\n  TRANSFER_IN\n  TRANSFER_OUT\n  ADJUSTMENT\n}\n\nenum StockistCheckStatus {\n  BELUM_REVIEW\n  BEDA\n  BENAR\n}\n\n// Status verifikasi H+1 untuk entri harian kas & bank — sengaja dipisah dari\n// StockistCheckStatus supaya kedua alur bisa berkembang sendiri-sendiri.\nenum DailyVerifyStatus {\n  BELUM_REVIEW\n  BENAR\n  BEDA\n}\n\n// Bagian 3 — Tunai (Kas): pocket kas rupiah, entitas sendiri (bukan reuse StockistPocket),\n// dimiliki 1 PT (Company) sama seperti StockistPocket — bukan per cabang.\nmodel KasPocket {\n  id        String   @id @default(cuid())\n  companyId String\n  name      String // \"Kas Besar\", \"Kas Operasional\", dst — daftar sendiri, beda dari StockistPocket\n  code      String?\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company      Company         @relation(fields: [companyId], references: [id])\n  dailyEntries KasDailyEntry[]\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\nmodel KasDailyEntry {\n  id           String            @id @default(cuid())\n  kasPocketId  String\n  date         DateTime          @db.Date\n  balance      Decimal           @default(0) // saldo tunai hari itu — user cuma isi ini, tanpa dimensi currency\n  note         String?\n  createdBy    String?\n  // Verifikasi H+1, sama polanya dengan StockistDailyCheck: saldo yang diisi hari ini\n  // baru bisa dikonfirmasi besoknya. Angka pengganti lewat CorrectionRequest.\n  verifyStatus DailyVerifyStatus @default(BELUM_REVIEW)\n  verifyNote   String?\n  verifiedBy   String?\n  verifiedAt   DateTime?\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  kasPocket KasPocket @relation(fields: [kasPocketId], references: [id])\n\n  @@unique([kasPocketId, date])\n  @@index([kasPocketId, date])\n}\n\n// Bagian 4 — Konfirmasi Kepala Cabang: hitung ulang manual kepala cabang atas total\n// stock (per item), total kas, dan total bank, dibandingkan dengan total sistem hasil\n// input teller dalam. Hanya kepala cabang yang bisa mengisi/melihat nilai IDR di sini.\nmodel StockistHeadConfirmation {\n  id                 String    @id @default(cuid())\n  companyId          String\n  companyStockItemId String\n  date               DateTime  @db.Date\n  confirmedQuantity  Decimal // total stock asli hasil hitung ulang kepala cabang (dalam satuan item)\n  // Legacy: dulu nilai IDR diisi per item. Sekarang kepala cabang hanya mengisi satu\n  // total IDR final untuk seluruh stock (lihat StockistTotalHeadConfirmation), jadi\n  // kolom ini tidak lagi diisi dari UI dan dibiarkan null untuk baris baru.\n  confirmedIdrValue  Decimal?\n  note               String?\n  confirmedBy        String?\n  confirmedAt        DateTime?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  company          Company          @relation(fields: [companyId], references: [id])\n  companyStockItem CompanyStockItem @relation(fields: [companyStockItemId], references: [id])\n\n  @@unique([companyId, companyStockItemId, date])\n  @@index([companyId, date])\n}\n\n// Total IDR final seluruh stock (valas + logam mulia) hasil hitung ulang kepala cabang,\n// satu angka per PT per tanggal — bukan lagi per item. Kuantitas per item tetap\n// dicocokkan baris per baris di StockistHeadConfirmation.\nmodel StockistTotalHeadConfirmation {\n  id                String    @id @default(cuid())\n  companyId         String\n  date              DateTime  @db.Date\n  confirmedIdrValue Decimal\n  note              String?\n  confirmedBy       String?\n  confirmedAt       DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  @@unique([companyId, date])\n  @@index([companyId, date])\n}\n\nmodel KasHeadConfirmation {\n  id                String    @id @default(cuid())\n  companyId         String\n  date              DateTime  @db.Date\n  confirmedIdrValue Decimal\n  note              String?\n  confirmedBy       String?\n  confirmedAt       DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  @@unique([companyId, date])\n  @@index([companyId, date])\n}\n\n// Konfirmasi total saldo bank (semua rekening PT, gabungan) oleh kepala cabang —\n// dibandingkan dengan total sistem = sum(DailyBankEntry.balance) tanggal itu.\nmodel BankHeadConfirmation {\n  id                String    @id @default(cuid())\n  companyId         String\n  date              DateTime  @db.Date\n  confirmedIdrValue Decimal\n  note              String?\n  confirmedBy       String?\n  confirmedAt       DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  @@unique([companyId, date])\n  @@index([companyId, date])\n}\n\nmodel CompanyHeadConfirmationTotal {\n  id        String   @id @default(cuid())\n  companyId String\n  date      DateTime @db.Date\n  totalIdr  Decimal // StockistTotalHeadConfirmation + KasHeadConfirmation + BankHeadConfirmation, hari itu\n  updatedAt DateTime @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  @@unique([companyId, date])\n}\n\n// Bagian 5 — Pengajuan Koreksi: saat verifikasi H+1 (stock / kas / bank harian) angkanya\n// dinyatakan tidak sesuai, angka pengganti TIDAK langsung dipakai. Dia disimpan di sini\n// sebagai pengajuan dan baru mengubah data setelah disetujui Owner / Super Admin.\n// Referensi target disimpan sebagai id polos (tanpa FK) + label snapshot, supaya satu tabel\n// bisa melayani tiga domain tanpa kolom relasi yang saling eksklusif.\nmodel CorrectionRequest {\n  id        String               @id @default(cuid())\n  companyId String\n  target    CorrectionTargetType\n  date      DateTime             @db.Date // tanggal data yang dikoreksi\n\n  // Hanya kolom yang relevan dengan `target` yang diisi.\n  pocketId           String? // CorrectionTargetType.STOCKIST — StockistPocket\n  companyStockItemId String? // CorrectionTargetType.STOCKIST — CompanyStockItem\n  kasPocketId        String? // CorrectionTargetType.KAS\n  bankAccountId      String? // CorrectionTargetType.BANK\n\n  targetLabel   String // snapshot nama target saat diajukan, mis. \"Kas Kecil — USD\"\n  currentValue  Decimal // angka yang tersimpan saat pengajuan dibuat\n  proposedValue Decimal // angka pengganti usulan\n  reason        String // alasan wajib dari pengaju\n\n  status       CorrectionStatus @default(PENDING)\n  requestedBy  String?\n  requestedAt  DateTime         @default(now())\n  decidedBy    String?\n  decidedAt    DateTime?\n  decisionNote String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company Company @relation(fields: [companyId], references: [id])\n\n  @@index([companyId, status, requestedAt])\n  @@index([status, requestedAt])\n  @@index([target, date])\n}\n\nenum CorrectionTargetType {\n  STOCKIST\n  KAS\n  BANK\n}\n\nenum CorrectionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// Transaksi Jual & Beli Valas — satu baris per transaksi nasabah di loket.\n//\n// Bentuknya sengaja BEDA dari modul harian (DailyStockEntry, KasDailyEntry,\n// DailyBankEntry): di sana satu baris per pocket per tanggal, di sini satu baris\n// per kejadian. Tidak ada kunci unik per tanggal — nol transaksi sehari adalah\n// keadaan normal, bukan \"belum diisi\".\n//\n// Sumber harganya adalah Harga Valas (`CurrencyPrice`): BUY memakai `buyPrice`\n// (kita membeli dari nasabah), SELL memakai `sellPrice`. Harga itu global dan\n// BERGERAK, jadi angkanya di-SNAPSHOT ke baris ini saat transaksi dibuat —\n// `rate` adalah kurs yang benar-benar dipakai dan `priceRate` harga yang berlaku\n// saat itu. Tanpa snapshot, laporan kemarin akan ikut berubah setiap kali harga\n// hari ini disimpan.\n//\n// Sengaja TIDAK memutasi `CurrencyStock`/`StockMutation`: stok valas dicatat\n// lewat input harian Stock & Kas (closing qty per tanggal, lalu di-cross-check).\n// Kalau modul ini ikut menulis ke sana, angka stok punya dua sumber kebenaran\n// yang tidak bisa direkonsiliasi. Transaksi di sini adalah catatan penjualan &\n// pembelian; stok tetap milik modul stockist.\nmodel ValasTransaction {\n  id String @id @default(cuid())\n\n  // PT wajib (sumbu scope izin), cabang opsional — mengikuti pola Branch? di\n  // seluruh repo: cabang boleh dihapus tanpa menghilangkan riwayat transaksinya.\n  companyId String\n  branchId  String?\n\n  // Nomor bukti yang dilihat nasabah, unik per PT. Format:\n  // \"{KODE_PT}/{JL|BL}/{YYMMDD}/{urut 4 digit}\" — lihat generateInvoiceNo.\n  invoiceNo String\n\n  // Tanggal transaksi (date-only, UTC-midnight seperti modul harian) supaya\n  // laporan per tanggal tidak bergantung zona waktu. Jam sebenarnya ada di\n  // `createdAt`.\n  date DateTime @db.Date\n\n  type ValasTransactionType\n\n  currencyId String\n  // Jumlah valas yang berpindah tangan, dalam satuan mata uangnya.\n  amount     Decimal  @db.Decimal(18, 4)\n  // Kurs yang BENAR-BENAR dipakai (IDR per 1 unit). Boleh berbeda dari\n  // `priceRate` kalau kasir menegosiasikan harga.\n  rate       Decimal  @db.Decimal(18, 4)\n  // Harga dari Harga Valas saat transaksi dibuat — pembanding untuk menilai\n  // seberapa jauh kurs dinego. Null kalau mata uangnya belum punya harga.\n  priceRate  Decimal? @db.Decimal(18, 4)\n  // amount × rate, dihitung server. Disimpan supaya laporan tidak perlu\n  // mengalikan ulang (dan tidak bisa berbeda dari yang tercetak di bukti).\n  totalIdr   Decimal  @db.Decimal(18, 2)\n\n  // ── Nasabah ───────────────────────────────────────────────────────────────\n  // Nama selalu wajib. Identitas (jenis + nomor) wajib di atas ambang\n  // IDENTITY_REQUIRED_THRESHOLD — lihat valas-transaction.service.ts.\n  customerName     String\n  customerPhone    String?\n  customerIdType   ValasCustomerIdType?\n  customerIdNumber String?\n  customerAddress  String?\n\n  paymentMethod ValasPaymentMethod @default(CASH)\n  // Rekening tujuan/asal saat pembayarannya transfer. Nullable karena mayoritas\n  // transaksi loket tunai.\n  bankAccountId String?\n\n  note String?\n\n  // ── Pembatalan ────────────────────────────────────────────────────────────\n  // Transaksi TIDAK pernah dihapus: bukti bernomor yang hilang dari daftar\n  // adalah lubang di jejak audit. Pembatalan menandai, dan barisnya tetap\n  // tampil dengan status VOID (dikeluarkan dari semua total).\n  status     ValasTransactionStatus @default(COMPLETED)\n  voidedAt   DateTime?\n  voidedBy   String?\n  voidReason String?\n\n  createdBy String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  company     Company      @relation(fields: [companyId], references: [id])\n  branch      Branch?      @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  currency    Currency     @relation(fields: [currencyId], references: [id])\n  bankAccount BankAccount? @relation(fields: [bankAccountId], references: [id], onDelete: SetNull)\n\n  @@unique([companyId, invoiceNo])\n  // Halaman membaca satu PT satu tanggal; laporan membaca rentang tanggal per PT.\n  @@index([companyId, date])\n  @@index([companyId, currencyId, date])\n  @@index([branchId, date])\n}\n\nenum ValasTransactionType {\n  // Perusahaan MEMBELI valas dari nasabah → pakai CurrencyPrice.buyPrice.\n  BUY\n  // Perusahaan MENJUAL valas ke nasabah → pakai CurrencyPrice.sellPrice.\n  SELL\n}\n\nenum ValasPaymentMethod {\n  CASH\n  TRANSFER\n}\n\nenum ValasTransactionStatus {\n  COMPLETED\n  VOID\n}\n\nenum ValasCustomerIdType {\n  KTP\n  SIM\n  PASSPORT\n  KITAS\n  NPWP\n  LAINNYA\n}\n"
}

